edge_var = {}
var_edge = {}
idx = 1
for i in range(18):
    for j in range(i+1, 18):
        if (i,j) not in fixed_set:
            edge_var[(i,j)] = idx
            var_edge[idx] = (i,j)
            idx += 1

n_vars = idx - 1
