        incident_vars = []
        for (a,b), var_idx in edge_var.items():
            if a == v or b == v:
                incident_vars.append(var_idx)
        if incident_vars:
            clauses = CardEnc.atleast(lits=incident_vars, bound=needed, top_id=n_vars)
            for clause in clauses:
                solver.add_clause(clause)
            print(f"Vertex {v}: current deg={current_deg}, need at least {needed} more, {len(incident_vars)} incident optional edges")

