# Check vertex-connectivity by checking if removing any subset of up to 3 vertices disconnects the graph
from itertools import combinations

def is_connected(adj, vertices):
    """Check if the subgraph induced by vertices is connected"""
    if len(vertices) <= 1:
        return True
    start = next(iter(vertices))
    visited = set()
    stack = [start]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for u in adj[v]:
            if u in vertices and u not in visited:
                stack.append(u)
    return len(visited) == len(vertices)

def vertex_connectivity(adj, n):
    """Compute vertex-connectivity by brute force for small n"""
    all_vertices = set(range(n))
    for k in range(1, 4):  # Check if removing k vertices can disconnect
        for removed in combinations(range(n), k):
            remaining = all_vertices - set(removed)
            if not is_connected(adj, remaining):
                return k  # Found a cut of size k
    # Check if removing 3 vertices can disconnect
    for removed in combinations(range(n), 3):
        remaining = all_vertices - set(removed)
        if not is_connected(adj, remaining):
            return 3
    # Check if removing 4 vertices can disconnect
    for removed in combinations(range(n), 4):
        remaining = all_vertices - set(removed)
        if not is_connected(adj, remaining):
            return 4
    return n  # Complete graph

